package edu.ankara.audiometer.domain.algorithm;
import edu.ankara.audiometer.domain.config.HughsonWestlakeConfig;import edu.ankara.audiometer.domain.model.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ThresholdDetectorTest { TonePresentation p(int order,int db,PatientResponse r){return new TonePresentation(Ear.RIGHT,new FrequencyHz(1000),new IntensityDbHL(db),order,Optional.of(r),PresentationDirection.ASCENDING,true);} @Test void detectsTwoOutOfThreeAscending(){ var list=List.of(p(1,20,PatientResponse.HEARD),p(2,20,PatientResponse.NOT_HEARD),p(3,20,PatientResponse.HEARD)); var d=ThresholdDetector.detectThreshold(list,HughsonWestlakeConfig.defaults()); assertTrue(d.reached()); assertEquals(20,d.threshold().orElseThrow().value()); } @Test void detectsThreeOutOfFiveAscending(){ var cfg=HughsonWestlakeConfig.defaults().withCriterion(ThresholdCriterion.THREE_OUT_OF_FIVE_ASCENDING); var list=List.of(p(1,30,PatientResponse.HEARD),p(2,30,PatientResponse.NOT_HEARD),p(3,30,PatientResponse.HEARD),p(4,30,PatientResponse.TIMEOUT),p(5,30,PatientResponse.HEARD)); assertTrue(ThresholdDetector.detectThreshold(list,cfg).reached()); } @Test void ignoresDescendingTrials(){ var d=new TonePresentation(Ear.RIGHT,new FrequencyHz(1000),new IntensityDbHL(10),1,Optional.of(PatientResponse.HEARD),PresentationDirection.DESCENDING,false); assertFalse(ThresholdDetector.detectThreshold(List.of(d,d,d),HughsonWestlakeConfig.defaults()).reached()); } }
